	//! Scalar function behavior field (None for non-scalar functions).
	std::optional<FunctionNullHandling> null_handling{};
	//! Scalar-only properties aligned with the ordered fields in `arguments`. A present list has exactly
	//! one entry per declaration slot, including one for a vararg declaration. `None` means no claims.
	std::optional<std::vector<std::string>> argument_monotonicity{};
