	//! base object) is a separate, shorter operator-facing note from `Meta.comment` — e.g. "deprecated, use
	//! v2". Both are static: there is no `COMMENT ON FUNCTION` RPC, unlike tables/views, whose `comment` is
	//! dynamically settable.
	std::string description{};
	//! Usage examples for the function.
	std::vector<FunctionExample> examples{};
	//! Category labels for the function.
	std::vector<std::string> categories{};
	//! Table-function capability (None for scalar functions).
	std::optional<bool> projection_pushdown{};
	//! Table-function capability (None for scalar functions).
	std::optional<bool> filter_pushdown{};
	//! Table-function capability (None for scalar functions).
	std::optional<bool> sampling_pushdown{};
	//! True if the table participates in DuckDB's late-materialization optimizer
	//! (`Meta.late_materialization`). The DuckDB extension only honours this when the table also exposes a
	//! rowid virtual column plus filter/projection pushdown — see GetScanFunctionImpl in the C++
	//! vgi_table_entry.cpp.
	std::optional<bool> late_materialization{};
	//! V2 expression semantics profiles.
	std::vector<std::string> filter_semantic_profiles{};
	//! Versioned extension filter functions.
	std::vector<FilterFunctionCapability> additional_filter_functions{};
	//! Versioned runtime-filter artifact algorithms.
	std::vector<RuntimeFilterAlgorithmCapability> runtime_filter_algorithms{};
	//! Reproducible evaluation-context profiles.
	std::vector<EvaluationContextCapability> filter_evaluation_contexts{};
	//! Whether the function preserves input ordering.
	std::optional<VgiOrderPreservation> order_preservation{};
	//! Maximum parallel workers. Uses ArrowType to specify int32 instead of the default int64.
	std::optional<int32_t> max_workers{};
	//! True if the function opts in to per-batch `vgi_batch_index` tagging: the worker emits an integer
	//! partition id in each Arrow batch's KeyValueMetadata; the DuckDB extension threads it through
	//! `TableFunction::get_partition_data` so ordered sinks (BatchCollector, BatchInsert, BatchCopyToFile,
	//! Limit) can reassemble parallel output in partition-id order. Opting in also skips the FIXED_ORDER
	//! MaxThreads=1 clamp; the source stays parallel and the sink does the ordering.
	bool supports_batch_index{};
	//! True if the function implements on_plan()/on_split(), i.e. the scan can be divided into named,
	//! independently redeemable units. A distributed engine needs this to retry a task without re-reading
	//! or skipping rows.
	bool supports_splits{};
	//! True if the worker applies pushed-down filters exactly, so the engine may drop its own filter above
	//! the scan rather than re-applying it.
	bool filters_exactly_applied{};
	//! True if the function exposes addressable positions in the data, enabling incremental and streaming
	//! reads. VGI supplies the addressability; the engine owns the checkpoint.
	bool supports_positions{};
	//! How long a split token stays redeemable, or None for unbounded. A client refuses a plan whose TTL is
	//! below its own scheduling horizon (seconds for DuckDB, hours for a Spark driver), because otherwise
	//! the failure lands at task start after the job has already burned that time.
	std::optional<int64_t> split_token_ttl_seconds{};
	//! Partition shape declared by the function over its `vgi.partition_column`-annotated bind-schema
	//! fields. When non-`NOT_PARTITIONED`, the DuckDB extension installs
	//! `TableFunction::get_partition_info` returning the corresponding `TablePartitionInfo` value so the
	//! planner can pick `PhysicalPartitionedAggregate` for `GROUP BY` queries (today, only
	//! `SINGLE_VALUE_PARTITIONS` materially changes planner behavior). Per-column annotation lives in the
	//! bind schema's field-level metadata — see `vgi.schema_utils.partition_field`.
	VgiPartitionKind partition_kind{};
	//! Aggregate function field (future).
	AggregateOrderDependent order_dependent = AggregateOrderDependent::NotOrderDependent;
	//! Aggregate function field (future).
	AggregateDistinctDependent distinct_dependent = AggregateDistinctDependent::NotDistinctDependent;
	//! True if the aggregate implements the window() callback.
	bool supports_window{};
	//! True if the aggregate opts into the streaming-partitioned protocol — `aggregate_streaming_open` /
	//! `_chunk` / `_close`. The DuckDB extension's optimizer rule may rewrite eligible LogicalWindow nodes
	//! to use this path.
	bool streaming_partitioned{};
	//! True if a table-in-out function declares a finalize/finish stage. The C++ extension uses this to
	//! conditionally register `in_out_function_final`; DuckDB rejects LATERAL with correlated input on
	//! functions that register a finalize callback.
	bool has_finalize{};
	//! Only meaningful when `function_type == FunctionType.TABLE_BUFFERING` (i.e. the function is
	//! registered through the Sink+Source path). When true, the source phase is single-threaded and
	//! `finalize_state_id`s drain in combine-returned order. Default false enables parallel finalize.
	bool source_order_dependent{};
	//! Only meaningful when `function_type == FunctionType.TABLE_BUFFERING`. When true, the SINK phase runs
	//! single-threaded — every process() call arrives in source order on one worker. Mutually exclusive
	//! with `requires_input_batch_index`.
	bool sink_order_dependent{};
	//! Only meaningful when `function_type == FunctionType.TABLE_BUFFERING`. When true, the C++ Sink
	//! operator declares `RequiredPartitionInfo()=BatchIndex()`; each process() RPC carries a
	//! globally-unique monotonic batch_index from DuckDB's source. Workers can sort by it in combine() to
	//! reconstruct source order under parallel ingest. Mutually exclusive with `sink_order_dependent`.
	bool requires_input_batch_index{};
	//! True for a blended `RowTransformFunction` — its positional args ARE its per-row input columns (real
	//! typed args, no `TABLE` placeholder), so one registration serves the literal / column / LATERAL call
	//! shapes. Set from `RowTransformFunction` subclassing; the C++ extension reads it to enter the in-out
	//! registration branch with real-typed args and drive the literal single-row scan-mode.
	bool input_from_args{};
	//! For a blended `RowTransformFunction`, the most input rows one worker call receives; the client
	//! splits each input chunk into calls of at most this many rows. Null sends a whole chunk.
	std::optional<int64_t> input_rows_per_call{};
	//! Settings required by the function.
	std::vector<std::string> required_settings{};
	//! Secrets required by the function (each entry has secret_type, optional secret_name, optional scope).
	std::vector<RequiredSecret> required_secrets{};
