//! One physical source backing a multi-branch scan.
//! Protocol type: ScanBranch.
struct ScanBranch {
	//! The DuckDB function to call for a *function* branch (e.g., `"read_parquet"`, `"iceberg_scan"`, or a
	//! VGI table function). The C++ rewriter resolves this name against DuckDB's function catalog and binds
	//! it at optimize time. Empty string for a catalog-table branch.
	std::string function_name{};
	Bytes arguments{};
	//! Optional SQL expression text (parsed by DuckDB's parser, bound against the branch's bound column
	//! list). The rewriter AND's this into every scan of this branch BEFORE filter pushdown, so the branch
	//! only ever sees rows in its declared scope. Used to make overlapping physical sources (Kafka 7d
	//! retention + Iceberg nightly batches with ~24h overlap) non-overlapping at scan time, without
	//! changing the worker code. `None` means unconstrained.
	std::optional<std::string> branch_filter{};
	//! Declares this branch as the INSERT target for the multi-branch table. At most one branch per table
	//! may set this true (enforced at catalog-load by the C++ extension — multiple writable arms would
	//! violate DuckDB's single- writable-catalog-per-transaction rule). When no branch is writable, the
	//! table is read-only. UPDATE/DELETE/MERGE remain refused on multi-branch tables regardless of this
	//! flag; the contract is INSERT-only until cross-arm semantics have customer-driven evidence.
	bool writable{};
	//! Catalog-table branch only — the attached catalog name (matches an `AttachCatalogInfo.alias`). `None`
	//! for function branches.
	std::optional<std::string> source_catalog{};
	//! Catalog-table branch only — the schema of the source table. `None` for function branches.
	std::optional<std::vector<std::string>> source_schema_path{};
	//! Catalog-table branch only — the base table name; its presence selects the catalog-table kind. `None`
	//! for function branches.
	std::optional<std::string> source_table{};
	//! Format branch only — the format to read (`parquet`, `csv`, `iceberg`, …). The client resolves it to
	//! that format's reader, so a worker can say "these files, this format" without knowing the reader's
	//! argument spelling.
	std::optional<std::string> format_name{};
	//! Format branch only — the paths/URIs to read. Required when `format_name` is set; a format branch
	//! naming no locations is rejected at catalog-load.
	std::vector<std::string> format_locations{};
	//! Format branch only — reader options, passed through as the reader's named arguments.
	Bytes format_options{};
	//! Function branch only — catalog schema `function_name` is registered in (`None` for a
	//! catalog-table/format branch, which has no VGI-side schema of its own, or a native DuckDB function).
	//! Not to be confused with `source_schema_path`, which names the schema of a catalog-table branch's
	//! *source table*, a different, older field.
	std::optional<std::vector<std::string>> schema_path{};
};
bool operator==(const ScanBranch &a, const ScanBranch &b);
inline bool operator!=(const ScanBranch &a, const ScanBranch &b) {
	return !(a == b);
}
