//! Decode row `row` of `batch` (protocol errors name `worker_path`).
void FromBatch(const VgiBatchPtr &batch, int64_t row, ScanBranch &out, const std::string &worker_path);

//! One named, independently redeemable unit of scan work.
//! Protocol type: ScanSplit.
struct ScanSplitWire {
	//! The worker's own opaque bytes naming this unit of work. Set this and nothing else; the framework
	//! stamps `token` from it.
	Bytes payload{};
	//! The framework-stamped (and, where a signing key exists, sealed) envelope around `payload`. Populated
	//! by the framework — a worker must not set it, and the client sends THIS back, not the payload.
	Bytes token{};
	//! Row estimate, or `None` if unknown.
	std::optional<int64_t> estimated_rows{};
	//! True if `estimated_rows` is exact rather than an estimate. Unlocks `Precision::Exact` / COUNT(*)
	//! from statistics.
	bool rows_exact{};
	//! Byte estimate. Load-bearing for engines that bin-pack (DataFusion weight, Trino SplitWeight); `None`
	//! degrades them to round-robin by count. DuckDB claims greedily and does not need it.
	std::optional<int64_t> estimated_bytes{};
	//! 2-row (min, max) Arrow batch in the existing `vgi_partition_values` encoding, one column per
	//! partition column. For SINGLE_VALUE_PARTITIONS min == max, so row 0 is the exact key — but only
	//! report partitioning when the split really is single-valued.
	std::optional<Bytes> partition_bounds{};
	//! Per-column statistics blob (same encoding as `table_function_statistics`).
	std::optional<Bytes> column_statistics{};
	//! Indices into `PlanResponse.locations` naming hosts where this split is cheap to read.
	std::optional<std::vector<int64_t>> location_ids{};
	//! Exclusive lower bound of this split's range in the data.
	std::optional<Bytes> start_position{};
	//! Inclusive upper bound; `None` means UNBOUNDED — a shard read forever. A bounded engine (Spark
	//! micro-batch) must refuse those.
	std::optional<Bytes> end_position{};
};
bool operator==(const ScanSplitWire &a, const ScanSplitWire &b);
