//! A companion catalog the client should ATTACH when this VGI catalog attaches.
//! Protocol type: AttachCatalogInfo.
struct AttachCatalogInfo {
	//! Catalog name to attach as. Also the `source_catalog` a catalog-table `ScanBranch` references.
	//! **Namespace this by your catalog identity** (e.g. `"acme_lake"`) so two workers don't both claim
	//! `"lake"` on the same client — collisions are rejected, never silently merged.
	std::string alias{};
	//! The ATTACH target — a path or DSN, e.g. `"ducklake:sqlite:/data/meta.sqlite"` or `"postgres:dbname=…
	//! host=…"`.
	std::string target{};
	//! DuckDB storage/db type (e.g. `"ducklake"`, `"postgres"`). Empty ⇒ the extension infers it from the
	//! `target` scheme prefix.
	std::string db_type{};
	//! Extra ATTACH options forwarded verbatim (e.g. DuckLake `DATA_PATH`). Keys are matched
	//! case-insensitively by DuckDB.
	std::map<std::string, std::string> options{};
	//! When true, attach hidden (excluded from `duckdb_databases()`); still resolvable by qualified name
	//! and by branches. Use for branch-only companions the user shouldn't see.
	bool hidden{};
	//! When true, a failure to attach (unreachable / conflict) fails the whole VGI ATTACH loudly. When
	//! false, the failure is logged and skipped; branches referencing it then error at bind.
	bool required{};
	//! Optional name of a credential to pre-resolve (via the catalog's Orchard secret provider) and inject
	//! into the companion's ATTACH options — for metadata connections (e.g. a postgres DSN) where the
	//! catch-all path-keyed secret lookup isn't enough. Empty ⇒ rely on the automatic catch-all provider
	//! for data-file creds.
	std::string secret_ref{};
};
