//! Extracted attach-option metadata for catalog discovery serialization.
//! Protocol type: AttachOptionSpec.
struct AttachOptionSpec {
	std::string name{};
	std::string description{};
	Bytes type{};
	std::optional<Bytes> default_value{};
	//! The caller must supply this option at `ATTACH` time. A catalog that cannot be attached without it
	//! advertises that fact at discovery, so a client can say so before attempting the attach rather than
	//! surfacing a failure that reads like an empty catalog. Mutually exclusive with `default` — an option
	//! that falls back to a value is by definition satisfiable without the caller.
	bool required{};
	//! The option carries a credential (an API key, token or password). It is still passed inline at
	//! `ATTACH`, but clients mask it, and the DuckDB extension redacts it from `duckdb_databases()`, keeps
	//! only a salted hash of it in its result-cache key, and never logs it. Keep it out of the SQL text
	//! with an expression, e.g. `api_key getenv('MYDB_API_KEY')`. Credential options MUST set this.
	//! Compatible with `required`. Allowed alongside a `default`, but a secret option should normally have
	//! none: a default credential is advertised in plain text to every client at discovery.
	bool secret{};
};
bool operator==(const AttachOptionSpec &a, const AttachOptionSpec &b);
inline bool operator!=(const AttachOptionSpec &a, const AttachOptionSpec &b) {
	return !(a == b);
}
