//! Result from attaching to a catalog.
//! Protocol type: method 'catalog_attach' result.
struct CatalogAttachResult {
	//! The unique id for the attached catalog.
	Bytes attach_opaque_data{};
	//! Indicate if the worker supports transactions or not. If false, all transaction related methods will
	//! not be called and all transaction_opaque_data parameters will be None.
	bool supports_transactions{};
	//! Indicate if tables support time travel.
	bool supports_time_travel{};
	//! Indicate that the catalog version id is frozen and the schema and object information will not
	//! change.
	bool catalog_version_frozen{};
	//! The initial catalog version, it increments when schemas, tables or other objects change.
	int64_t catalog_version{};
	//! Indicate if the attach_opaque_data must be persisted across commands. True: Catalog is stateful;
	//! attach_opaque_data represents a session. False: Catalog is stateless; CLI can auto-attach on each
	//! command.
	bool attach_opaque_data_required = true;
	//! Raw root schema name, or None when there is no implicit default.
	std::optional<std::string> default_schema{};
	//! Extension options (settings) exposed by this catalog/worker. Each ExtensionOption is serialized as
	//! bytes for Arrow compatibility.
	std::vector<Bytes> settings{};
	//! Secret types registered with DuckDB's SecretManager. Each SecretTypeSpec is serialized as bytes for
	//! Arrow compatibility.
	std::vector<Bytes> secret_types{};
	//! Companion catalogs the client should ATTACH alongside this VGI catalog (lakehouse federation). Each
	//! `AttachCatalogInfo` is serialized as bytes for Arrow compatibility. Attached at VGI-attach time;
	//! detached (refcounted) on DETACH. See `AttachCatalogInfo` and `docs/companion_catalogs.md`.
	std::vector<Bytes> attach_catalogs{};
	//! Optional comment describing this catalog/database.
	std::optional<std::string> comment{};
	//! Optional key-value tags associated with this catalog/database.
	std::map<std::string, std::string> tags{};
	//! Whether any tables in this catalog can provide column statistics. Global gate — if False,
	//! GetStatistics() returns nullptr for all tables.
	bool supports_column_statistics{};
	//! Functions this catalog asks the client to publish into the *global* function namespace (DuckDB's
	//! `system.main`), in addition to their normal schema-qualified registration. Each `FunctionInfo` is
	//! serialized as bytes for Arrow compatibility. `name`/`schema_path` stay the real dispatch coordinates
	//! — the client derives the globally visible name by applying `global_function_prefix`. Registration is
	//! first-attach-wins: a name already owned by a different worker is skipped (logged), and the ATTACH
	//! still succeeds. Empty list = this catalog publishes nothing globally. See
	//! `docs/global-functions.md`.
	std::vector<Bytes> global_functions{};
	//! Prefix applied to every `global_functions` entry to form its globally visible name
	//! (`<prefix>_<name>`). Empty string = publish bare names, which is more collision-prone; prefer a
	//! prefix that identifies the worker.
	std::string global_function_prefix{};
	//! Concrete data version the worker resolved for this attach. `None` = worker has no opinion or the
	//! request omitted data_version_spec.
	std::optional<std::string> resolved_data_version{};
	//! Concrete implementation version the worker resolved for this attach. `None` = worker has no opinion
	//! or the request omitted implementation_version.
	std::optional<std::string> resolved_implementation_version{};
	//! Whether the client may load the whole catalog with one `catalog_contents` call instead of
	//! `catalog_schemas` plus a `catalog_schema_contents_*` call per schema and kind. Older workers omit it
	//! and read as `False`.
	bool supports_catalog_contents{};
	//! Current provider profile advertisement, not authorization.
	std::optional<Bytes> catalog_capabilities{};
	//! Profiles selected for this attachment; absent means none.
	std::optional<Bytes> selected_capabilities{};
	//! Immutable query agreement selected from the client's offer, or None.
	std::optional<QueryCapabilities> query_pushdown{};
};
