//! Result of the scan-planning phase: named splits plus plan-level facts.
//! Protocol type: method 'table_function_plan' result.
struct TableFunctionPlanResult {
	//! One `ScanSplit` per unit of work. Return the OBJECTS from `on_plan`; the framework stamps each one's
	//! token and serializes it once. Handing back pre-serialized blobs instead makes the framework open and
	//! re-serialize each to carry its token — a full Arrow IPC stream both ways, measured at roughly two
	//! thirds of the cost of planning — so it is supported but never the right choice from Python. On the
	//! wire each split is its own IPC blob in a `list<binary>` column (the `ScanBranchesResult` shape).
	std::vector<Bytes> splits{};
	//! Continuation cursors. Normally 0 or 1. More than one means parallel enumeration, which is only sound
	//! if the cursors partition the remaining enumeration **disjointly and exhaustively** — no split may be
	//! reachable from two cursors. No client checks this: a dedup was tried and removed — it needed a set
	//! holding a copy of every token (hundreds of MB on a large plan, paid by every scan), it compared
	//! token bytes so it could never work on a keyed worker where each mint uses a fresh nonce, and the
	//! most a client can do with a duplicate is refuse anyway. Violating it returns **duplicate rows**,
	//! silently.
	std::optional<std::vector<Bytes>> next_cursors{};
	//! Identifier for this scan, echoed on every split init. Scopes cross-process `BoundStorage` exactly as
	//! it does elsewhere.
	std::optional<Bytes> execution_id{};
	//! Opaque per-init state threaded into each split's stream.
	std::optional<Bytes> init_opaque_data{};
	//! Normative cap on how many splits may be in flight at once.
	std::optional<int64_t> max_workers{};
	//! Estimate of the total split count.
	std::optional<int64_t> estimated_total_splits{};
	//! Whole-scan row estimate, for CBO / estimateStatistics without forcing full enumeration.
	std::optional<int64_t> estimated_total_rows{};
	//! Whole-scan byte estimate.
	std::optional<int64_t> estimated_total_bytes{};
	//! The catalog counter this plan is pinned to — the one that *moves* within an attach, unlike
	//! `resolved_data_version` which is fixed at attach.
	std::optional<int64_t> catalog_version{};
	//! Which consistency anchor the tokens bind — `catalog` or `transaction` (reuses the CACHE_SCOPE_*
	//! vocabulary). Transaction-scoped plans are not cacheable and are not redeemable after commit or
	//! rollback.
	std::string scope = "catalog";
	//! Hoisted host list; splits index into it via `location_ids`.
	std::optional<std::vector<std::string>> locations{};
	//! Serialized `PartitionTransform` records describing how partition columns are derived. Report none
	//! unless every split really is single-valued.
	std::optional<std::vector<Bytes>> partitioning{};
	//! Serialized `SortField` records describing ordering *within* each split.
	std::optional<std::vector<Bytes>> sort_order{};
	//! How long this plan may be reused. Ignored for transaction-scoped plans.
	std::optional<int64_t> cache_max_age_seconds{};
	//! What the worker actually started from.
	std::optional<Bytes> start_position{};
	//! The data frontier resolved at plan time — this is `latestOffset()`. Checkpoint it and pass it back
	//! as the next `start_position`.
	std::optional<Bytes> end_position{};
};
